                        if ((tr->langopts.numbers2 & NUM2_ENGLISH_NUMERALS) && !(wtab->flags & FLAG_CHAR_REPLACED)) {
                                // for this language, speak English numerals (0-9) with the English voice
                                sprintf(word_phonemes, "%c", phonSWITCH);
